public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the shortest string to limit candidate substrings
    String minString = null;
    for (String s : strings) {
        if (s == null) continue; // treat null as empty string
        if (minString == null || s.length() < minString.length()) {
            minString = s;
        }
    }
    if (minString == null || minString.length() == 0) {
        return 0;
    }

    int minLen = minString.length();

    // Iterate from longest possible length down to 1
    for (int len = minLen; len >= 1; len--) {
        Set<String> candidateSet = new HashSet<>();

        // Generate all unique substrings of length 'len' from the shortest string
        for (int i = 0; i <= minString.length() - len; i++) {
            candidateSet.add(minString.substring(i, i + len));
        }

        // For each candidate, check if it or its reverse appears in every string
        for (String candidate : candidateSet) {
            String reversed = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;

            for (String t : strings) {
                if (t == null) {
                    ok = false;
                    break;
                }
                if (!(t.contains(candidate) || t.contains(reversed))) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                return len; // Found the largest valid length
            }
        }
    }

    return 0; // No common substring found
}

public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int maxLen = first.length();
    for (int len = maxLen; len > 0; len--) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        for (int i = 0; i + len <= maxLen; i++) {
            String sub = first.substring(i, i + len);
            if (!seen.add(sub)) {
                continue; // skip duplicate substrings
            }
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (int k = 1; k < strings.size(); k++) {
                String s = strings.get(k);
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

