public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.HashSet<Integer> set = new java.util.HashSet<>();
    for (int num : numbers) {
        set.add(num);
    }
    int count = 0;
    for (int num : numbers) {
        long doubled = 2L * num;
        if (doubled > Integer.MAX_VALUE || doubled < Integer.MIN_VALUE) {
            continue; // no int value can match this
        }
        if (set.contains((int) doubled)) {
            count++;
        }
    }
    return count;
}

public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    // Build frequency map
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        if (n % 2 == 0) {
            int half = n / 2;
            if (half == n) { // case n == 0
                if (freq.get(n) > 1) {
                    count++;
                }
            } else {
                if (freq.containsKey(half)) {
                    count++;
                }
            }
        }
    }
    return count;
}

