            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            if (!inBounds.test(x1, y1) || !inBounds.test(x2, y2)) continue;
            String a = toKey.apply(x1, y1);
            String b = toKey.apply(x2, y2);
            graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
    }

    // Breadth-first search for connectivity
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (visited.add(nb)) {
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (start == null || end == null || start.length != 1 || end.length != 1) {
        throw new IllegalArgumentException("start and end must be int arrays of length 1");
    }
    int startId = start[0];
    int endId = end[0];
    if (startId < 0 || startId >= n || endId < 0 || endId >= n) {
        throw new IllegalArgumentException("start or end index out of bounds");
    }

    // Build adjacency list
    @SuppressWarnings("unchecked")
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    if (paths != null) {
        for (int[] edge : paths) {
            if (edge == null || edge.length != 2) {
                throw new IllegalArgumentException("Each path must contain exactly two node indices");
            }
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                continue; // ignore invalid edges
            }
            adj[u].add(v);
            adj[v].add(u); // assuming undirected paths
        }
    }

    // Breadth-First Search to check connectivity
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    queue.add(startId);
    visited[startId] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endId) {
            return "can be travelled";
        }
        for (int neighbor : adj[current]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length != end.length) {
        return "cannot be travelled";
    }
    // Helper to encode a coordinate array into a string key
    java.util.function.Function<int[], String> coordToKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

    for (int[] p : paths) {
        // Expect path format: [x1, y1, x2, y2, ...] where the first half is first coord
        int coordLen = start.length;
        if (p.length != coordLen * 2) {
            // Skip malformed path entries
            continue;
        }
        int[] a = new int[coordLen];
        int[] b = new int[coordLen];
        System.arraycopy(p, 0, a, 0, coordLen);
        System.arraycopy(p, coordLen, b, 0, coordLen);
        String keyA = coordToKey.apply(a);
        String keyB = coordToKey.apply(b);
        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.getOrDefault(current, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (visited.contains(nb)) continue;
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(nb);
            queue.add(nb);
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Handle null inputs
    if (start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    // Convert start and end coordinates to a string key
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    // Quick check: if start and end are the same intersection
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build graph adjacency list
    Map<String, List<String>> graph = new HashMap<>();
    for (int[] path : paths) {
        // Expecting each path to contain four integers: x1, y1, x2, y2
        if (path == null || path.length != 4) {
            continue; // skip invalid path entries
        }
        String from = path[0] + "," + path[1];
        String to = path[2] + "," + path[3];

        graph.computeIfAbsent(from, k -> new ArrayList<>()).add(to);
        graph.computeIfAbsent(to, k -> new ArrayList<>()).add(from);
    }

    // Breadth-first search for connectivity
    Set<String> visited = new HashSet<>();
    Deque<String> queue = new ArrayDeque<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        List<String> neighbors = graph.getOrDefault(current, Collections.emptyList());
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (start == null || end == null || paths == null) {
            throw new IllegalArgumentException("Input arrays cannot be null");
        }
        int dims = start.length;
        if (end.length != dims) {
            throw new IllegalArgumentException("Start and end coordinates must have the same dimension");
        }
        // Validate coordinate values against n
        for (int v : start) {
            if (v < 0 || v >= n) throw new IllegalArgumentException("Start coordinate out of bounds");
        }
        for (int v : end) {
            if (v < 0 || v >= n) throw new IllegalArgumentException("End coordinate out of bounds");
        }
        // Helper to convert coordinate array to string key
        java.util.function.Function<int[], String> toKey = coord -> java.util.Arrays.stream(coord)
                .mapToObj(Integer::toString)
                .reduce((a, b) -> a + "," + b)
                .orElse("");
        java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

        // Build adjacency from paths
        for (int[] path : paths) {
            if (path == null || path.length != 2 * dims) {
                throw new IllegalArgumentException("Each path must contain 2*dimension coordinates");
            }
            int[] a = new int[dims];
            int[] b = new int[dims];
            System.arraycopy(path, 0, a, 0, dims);
            System.arraycopy(path, dims, b, 0, dims);
            // validate bounds
            for (int v : a) {
                if (v < 0 || v >= n) throw new IllegalArgumentException("Path coordinate out of bounds");
            }
            for (int v : b) {
                if (v < 0 || v >= n) throw new IllegalArgumentException("Path coordinate out of bounds");
            }
            String keyA = toKey.apply(a);
            String keyB = toKey.apply(b);
            adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
            adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        }

        String startKey = toKey.apply(start);
        String endKey = toKey.apply(end);

        if (startKey.equals(endKey)) return "can be travelled";

        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.add(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            java.util.List<String> neigh = adj.getOrDefault(cur, java.util.Collections.emptyList());
            for (String next : neigh) {
                if (next.equals(endKey)) return "can be travelled";
                if (!visited.contains(next)) {
                    visited.add(next);
                    queue.add(next);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        // For any runtime or validation issue, fall back to cannot be travelled
        return "cannot be travelled";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) return null;
    java.time.format.DateTimeFormatter parser = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.ENGLISH);
    try {
        java.time.LocalDate localDate = java.time.LocalDate.parse(date.trim(), parser);
        String monthName = localDate.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (Exception e) {
        return null;
    }
}

