public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trimCount = n / 20; // 5% of n
    if (trimCount == 0) {
        // If 5% is less than 1 element, return the mean of all elements
        long total = 0;
        for (int v : arr) {
            total += v;
        }
        return total / (double) n;
    }
    int[] copy = arr.clone();
    java.util.Arrays.sort(copy);
    long sum = 0;
    for (int i = trimCount; i < n - trimCount; i++) {
        sum += copy[i];
    }
    int remaining = n - 2 * trimCount;
    return sum / (double) remaining;
}

public double trimMean(int[] arr) {
