    int k = (int)Math.floor(n * 0.05);
    int[] sorted = java.util.Arrays.copyOf(arr, n);
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    int count = n - 2 * k;
    return count > 0 ? sum / (double)count : 0.0;
}

