public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        freq[rem]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue; // already handled for even k
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false; // invalid input
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair all elements
    }
    if (n == 0) {
        return true; // empty array can be considered trivially paired
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // ensure non‑negative remainder
        count[r]++;
    }
    // Check remainder 0 group
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, check middle group
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check pairs of complementary remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            // already handled when k even
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }
    Map<Integer, Integer> remainderCount = new HashMap<>();
    // Count frequency of each remainder modulo k
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        remainderCount.put(rem, remainderCount.getOrDefault(rem, 0) + 1);
    }
    // Check conditions for each remainder
    for (Map.Entry<Integer, Integer> entry : remainderCount.entrySet()) {
        int rem = entry.getKey();
        int count = entry.getValue();
        int complement = (k - rem) % k;
        if (rem == complement) {
            if (count % 2 != 0) {
                return false; // need even count for 0 or k/2 residues
            }
        } else {
            int compCount = remainderCount.getOrDefault(complement, 0);
            if (count != compCount) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        count[r]++;
    }
    // Remainder 0 must have even count
    if (count[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r < k; r++) {
        int comp = k - r;
        if (r == comp) { // only possible when k is even
            if (count[r] % 2 != 0) {
                return false;
            }
        } else if (r < comp) {
            if (count[r] != count[comp]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) return false;
    int n = arr.length;
    if (n % 2 != 0) return false; // need to pair all elements
    if (k <= 0) return false; // invalid divisor

    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        freq[rem]++;
    }

    // Remainder 0 elements must pair among themselves
    if (freq[0] % 2 != 0) return false;

    // Check complementary remainders
    for (int i = 1; i <= k / 2; i++) {
        int j = k - i;
        if (i == j) { // occurs when k is even and i == k/2
            if (freq[i] % 2 != 0) return false;
        } else {
            if (freq[i] != freq[j]) return false;
        }
    }

    return true;
}

