private int dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple, boolean isRoot) {
    int time = 0;
    for (int next : adj[node]) {
        if (next == parent) continue;
        int t = dfs(next, node, adj, hasApple, false);
        if (t > 0 || hasApple[next]) {
            time += t + 2;
        }
    }
    // If this node itself has an apple and there are no apples in subtrees,
    // we don't need to add extra time here. For root we simply return total.
    if (time == 0 && !hasApple[node] && !isRoot) {
        return 0; // no apple in this subtree (including current)
    }
    return time;
}

