}

private boolean dfs(int node, int parent, java.util.List<Integer>[] adj, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int nei : adj[node]) {
        if (nei == parent) continue;
        if (dfs(nei, node, adj, hasApple, time)) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

