public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder sb = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending phase
        java.util.Map.Entry<Character, Integer> entry = freq.firstEntry();
        char cur = entry.getKey();
        sb.append(cur);
        int cnt = freq.get(cur);
        if (cnt == 1) {
            freq.remove(cur);
        } else {
            freq.put(cur, cnt - 1);
        }
        remaining--;
        while (remaining > 0) {
            java.util.Map.Entry<Character, Integer> nextEntry = freq.higherEntry(cur);
            if (nextEntry == null) break;
            char next = nextEntry.getKey();
            sb.append(next);
            cnt = freq.get(next);
            if (cnt == 1) {
                freq.remove(next);
            } else {
                freq.put(next, cnt - 1);
            }
            remaining--;
            cur = next;
        }
        if (remaining == 0) break;

        // Descending phase
        java.util.Map.Entry<Character, Integer> decEntry = freq.lastEntry();
        cur = decEntry.getKey();
        sb.append(cur);
        cnt = freq.get(cur);
        if (cnt == 1) {
            freq.remove(cur);
        } else {
            freq.put(cur, cnt - 1);
        }
        remaining--;
        while (remaining > 0) {
            java.util.Map.Entry<Character, Integer> prevEntry = freq.lowerEntry(cur);
            if (prevEntry == null) break;
            char prev = prevEntry.getKey();
            sb.append(prev);
            cnt = freq.get(prev);
            if (cnt == 1) {
                freq.remove(prev);
            } else {
                freq.put(prev, cnt - 1);
            }
            remaining--;
            cur = prev;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    java.lang.StringBuilder sb = new java.lang.StringBuilder();

    while (!map.isEmpty()) {
        // Ascending sequence
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        while (entry != null) {
            char ch = entry.getKey();
            sb.append(ch);
            int cnt = entry.getValue() - 1;
            if (cnt > 0) {
                map.put(ch, cnt);
            } else {
                map.remove(ch);
            }
            entry = map.higherEntry(entry.getKey());
        }
        if (map.isEmpty()) {
            break;
        }

        // Descending sequence
        entry = map.lastEntry();
        while (entry != null) {
            char ch = entry.getKey();
            sb.append(ch);
            int cnt = entry.getValue() - 1;
            if (cnt > 0) {
                map.put(ch, cnt);
            } else {
                map.remove(ch);
            }
            entry = map.lowerEntry(entry.getKey());
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int total = 0;
    for (int v : nums) total += v;

    int mid = n / 2;
    int[] first = new int[mid];
    int[] second = new int[n - mid];
    System.arraycopy(nums, 0, first, 0, mid);
    System.arraycopy(nums, mid, second, 0, n - mid);

    int len1 = first.length;
    int len2 = second.length;

    // Generate all subset sums for each half, grouped by subset size
    @SuppressWarnings("unchecked")
    List<Integer>[] sums1 = new List[len1 + 1];
    @SuppressWarnings("unchecked")
    List<Integer>[] sums2 = new List[len2 + 1];
    for (int i = 0; i <= len1; i++) sums1[i] = new ArrayList<>();
    for (int i = 0; i <= len2; i++) sums2[i] = new ArrayList<>();

    // First half
    for (int mask = 0; mask < (1 << len1); mask++) {
        int cnt = Integer.bitCount(mask);
        int s = 0;
        for (int j = 0; j < len1; j++) {
            if ((mask & (1 << j)) != 0) s += first[j];
        }
        sums1[cnt].add(s);
    }

    // Second half
    for (int mask = 0; mask < (1 << len2); mask++) {
        int cnt = Integer.bitCount(mask);
        int s = 0;
        for (int j = 0; j < len2; j++) {
            if ((mask & (1 << j)) != 0) s += second[j];
        }
        sums2[cnt].add(s);
    }

    // Convert sums2 lists to sets for quick lookup
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] sets2 = new HashSet[len2 + 1];
    for (int i = 0; i <= len2; i++) {
        sets2[i] = new HashSet<>(sums2[i]);
    }

    // Try all possible split sizes
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) continue; // target sum not integer
        int target = (total * k) / n;

        // Split k into k1 from first half, k2 from second half
        int minK1 = Math.max(0, k - len2);
        int maxK1 = Math.min(k, len1);
        for (int k1 = minK1; k1 <= maxK1; k1++) {
            int k2 = k - k1;
            for (int s1 : sums1[k1]) {
                int needed = target - s1;
                if (sets2[k2].contains(needed)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int total = 0;
    for (int v : nums) total += v;
    // Try each possible subset size
    for (int k = 1; k <= n / 2; k++) {
        long prod = 1L * total * k;
        if (prod % n != 0) continue;
        int target = (int) (prod / n);
        // DP: dp[s][t] = can we achieve sum t with exactly s elements
        boolean[][] dp = new boolean[k + 1][target + 1];
        dp[0][0] = true;
        for (int num : nums) {
            // Update from high to low to avoid reuse within same num
            for (int s = k; s >= 1; s--) {
                for (int t = target; t >= num; t--) {
                    if (dp[s - 1][t - num]) {
                        dp[s][t] = true;
                    }
                }
            }
        }
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Iterate over possible subset sizes
    for (int k = 1; k <= n / 2; k++) {
        // Check if a subset of size k can have an integer average equal to the array average
        long product = 1L * totalSum * k;
        if (product % n != 0) continue;
        int targetSum = (int) (product / n);
        // DP: dp[sz][s] indicates whether a subset of size sz with sum s is achievable
        boolean[][] dp = new boolean[k + 1][totalSum + 1];
        dp[0][0] = true;
        for (int num : nums) {
            for (int sz = k; sz >= 1; sz--) {
                for (int s = totalSum; s >= num; s--) {
                    if (dp[sz - 1][s - num]) {
                        dp[sz][s] = true;
                    }
                }
            }
        }
        if (dp[k][targetSum]) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    long total = 0L;
    for (int num : nums) total += num;
    int maxK = n / 2;
    java.util.List<java.util.HashSet<Integer>> dp = new java.util.ArrayList<>(maxK + 1);
    for (int i = 0; i <= maxK; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);
    int processed = 0;
    for (int num : nums) {
        processed++;
        int limit = Math.min(processed, maxK);
        for (int k = limit; k >= 1; k--) {
            java.util.HashSet<Integer> prevSet = dp.get(k - 1);
            java.util.HashSet<Integer> currSet = dp.get(k);
            for (int prevSum : prevSet) {
                int newSum = prevSum + num;
                currSet.add(newSum);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        long kTotal = total * k;
        if (kTotal % n == 0) {
            int target = (int) (kTotal / n);
            if (dp.get(k).contains(target)) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    // dp[i] stores all achievable sums using exactly i elements
    @SuppressWarnings("unchecked")
    Set<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        for (int i = n - 1; i >= 0; i--) {
            if (!dp[i].isEmpty()) {
                for (int s : dp[i]) {
                    dp[i + 1].add(s + num);
                }
            }
        }
    }

    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    // dp[i] = min cost to reach step i
    // dp[0] = dp[1] = 0 (starting points)
    int prevPrev = 0; // dp[0]
    int prev = 0;     // dp[1]
    int curr = 0;
    for (int i = 2; i <= n; i++) {
        curr = Math.min(prev + cost[i - 1], prevPrev + cost[i - 2]);
        prevPrev = prev;
        prev = curr;
    }
    return prev;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int prevPrev = cost[0];
    int prev = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prevPrev, prev);
        prevPrev = prev;
        prev = current;
    }
    return Math.min(prevPrev, prev);
}

