public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0; // No steps to climb, cost is zero
    }
    int n = cost.length;
    if (n == 1) {
        // You can start from step 1 (outside of array) and reach the top without paying
        return 0;
    }
    int prev2 = cost[0]; // cost to reach step 0
    int prev1 = cost[1]; // cost to reach step 1
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2); // choose cheaper path to step i
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2); // step to top from either of the last two steps
}

