public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int leftCount = 0;
    for (char ch : s.toCharArray()) {
        if (ch == '(') {
            leftCount++;
        } else { // ch == ')'
            if (leftCount > 0) {
                leftCount--;
            } else {
                // Need to insert a '(' before this ')'
                insertions++;
            }
        }
    }
    // Any remaining unmatched '(' need ')'
    return insertions + leftCount;
}

