public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int half = n / 2;          // floor(n/2)
    return half * (n - half);  // floor(n/2) * ceil(n/2)
}

public int minOperations(int n) {
    if (n <= 1) {
        return 0; // array of length 0 or 1 is already equal
    }
    long result;
    if ((n & 1) == 0) { // even n
        long half = n / 2L;
        result = half * half; // (n/2)^2
    } else { // odd n
        long k = (n - 1L) / 2L;
        result = k * (k + 1); // k(k+1) = (n^2-1)/4
    }
    return (int) result;
}

public int minOperations(int n) {
    if (n <= 0) return 0;
    long s = ((long) n - 1) / 2 + 1; // first index with arr[i] > n
    long c = (long) n - s;           // number of indices after s
    long ops = s * c;                // sum of positive differences
    return (int) ops;
}

