public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) break;
        fibs.add(next);
    }

    // greedy subtraction from the largest Fibonacci number
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        while (remaining >= fib) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

