public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        switch (log) {
            case "../":
                if (depth > 0) {
                    depth--;
                }
                break;
            case "./":
                // stay in the same folder
                break;
            default:
                // Any other string is treated as a directory entry
                depth++;
                break;
        }
    }
    return depth;
}

public int minOperations(String[] logs) {
    // Guard against null or empty input
    if (logs == null || logs.length == 0) {
        return 0;
    }

    int depth = 0;

    for (String log : logs) {
        if ("..".equals(log)) {
            // Move up one level if possible
            if (depth > 0) {
                depth--;
            }
        } else if (".equals(log)) {
            // Stay in the current folder: no change
            continue;
        } else {
            // Any other folder operation (e.g., "d1/") moves into a subfolder
            depth++;
        }
    }

    // The 'depth' now represents the minimum number of upward steps needed
    // to return to the main folder
    return depth;
}

