public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length must be positive");
    }
    // Minimum possible sum is n (all 'a'), maximum is n*26 (all 'z')
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k is out of feasible range for given n");
    }

    char[] result = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // how many extra points we need to distribute

    // Distribute the remaining value starting from the end to keep lexicographic order minimal
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int increment = Math.min(remaining, 25); // max we can add to an 'a'
        result[i] = (char) (result[i] + increment);
        remaining -= increment;
    }

    return new String(result);
}

