public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    int maxVal = 0;
    for (int val : arr) maxVal = Math.max(maxVal, val);
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    boolean[] used = new boolean[n];
    // Use an array to hold the current permutation's indices
    java.util.ArrayList<Integer> perm = new java.util.ArrayList<>(n);
    java.util.function.IntSupplier result = new java.util.function.IntSupplier() { int val = 0; public int getAsInt() { return val;} };
    java.util.function.IntConsumer increment = v -> result.val++;

    java.util.function.BiConsumer<int[], Integer> dfs = new java.util.function.BiConsumer<int[], Integer>() {
        @Override
        public void accept(int[] state, Integer lastIdx) {
            int pos = perm.size();
            if (pos == n) {
                increment.accept(0);
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue; // skip duplicates
                if (pos > 0 && !isSquare[arr[lastIdx.intValue()] + arr[i]]) continue;
                used[i] = true;
                perm.add(i);
                dfs.accept(state, i);
                perm.remove(perm.size() - 1);
                used[i] = false;
            }
        }
    };

    dfs.accept(arr, -1); // -1 indicates no last element
    return result.getAsInt();
}

