public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int n = A.length;
    int totalMask = 1 << n;
    int[][] dp = new int[totalMask][n];
    // initialize starting positions
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // helper to check perfect square
    java.util.function.IntPredicate isPerfectSquare = (int sum) -> {
        int r = (int) Math.sqrt(sum);
        return r * r == sum;
    };
    // iterate over all masks
    for (int mask = 1; mask < totalMask; mask++) {
        for (int last = 0; last < n; last++) {
            int cur = dp[mask][last];
            if (cur == 0) continue;
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue; // already used
                if (isPerfectSquare.test(A[last] + A[nxt])) {
                    dp[mask | (1 << nxt)][nxt] += cur;
                }
            }
        }
    }
    int fullMask = totalMask - 1;
    int result = 0;
    for (int last = 0; last < n; last++) {
        result += dp[fullMask][last];
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    // stack to keep indices of bars, with an initial sentinel -1
    int[] stack = new int[n + 1];
    int top = 0;
    stack[top] = -1;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        // Pop while the current height is less than the height at stack's top index
        while (top > 0 && heights[stack[top]] > currentHeight) {
            int height = heights[stack[top--]];
            int width = i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

