    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    if (len <= 1) {
        return -1; // No rearrangement possible
    }

    // Find the largest index i such that digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // Digits are in non‑increasing order; no larger permutation
    }

    // Find the largest index j greater than i such that digits[j] > digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the subarray digits[i+1 .. len-1]
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
    }

    if (result > Integer.MAX_VALUE) {
        return -1; // Overflow case
    }
    return (int) result;
}

