public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return java.util.Collections.emptyList();
    }
    return buildCenterSymmetric(n, true);
}

private static List<String> buildCenterSymmetric(int length, boolean top) {
    if (length == 0) {
        return java.util.Collections.singletonList("");
    }
    if (length == 1) {
        return java.util.Arrays.asList("0", "1", "8");
    }

    List<String> sub = buildCenterSymmetric(length - 2, false);
    List<String> result = new java.util.ArrayList<>();
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'} };

    for (String inner : sub) {
        for (char[] pair : pairs) {
            if (top && pair[0] == '0') {
                continue; // skip leading zero for top level
            }
            result.add(pair[0] + inner + pair[1]);
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'8', '8'}, {'6', '9'}, {'9', '6'} };
    boolean isSingle = (n == 1);
    char[] current = new char[n];
    backtrack(current, 0, n - 1, pairs, result, isSingle);
    return result;
}

private static void backtrack(char[] cur, int left, int right, char[][] pairs,
                               List<String> result, boolean isSingle) {
    if (left > right) {
        result.add(new String(cur));
        return;
    }
    if (left == right) { // middle digit for odd length
        for (char c : new char[] {'0', '1', '8'}) {
            cur[left] = c;
            backtrack(cur, left + 1, right - 1, pairs, result, isSingle);
        }
        return;
    }
    for (char[] pair : pairs) {
        if (left == 0 && !isSingle && pair[0] == '0') {
            continue; // no leading zero for multi-digit numbers
        }
        cur[left] = pair[0];
        cur[right] = pair[1];
        backtrack(cur, left + 1, right - 1, pairs, result, isSingle);
    }
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) return new java.util.ArrayList<>();
    return build(n, n);
}

private static java.util.List<String> build(int n, int total) {
    if (n == 0) return java.util.Arrays.asList("");
    if (n == 1) return java.util.Arrays.asList("0", "1", "8");
    java.util.List<String> inner = build(n - 2, total);
    java.util.List<String> result = new java.util.ArrayList<>();
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    for (String sub : inner) {
        for (char[] p : pairs) {
            if (n == total && p[0] == '0') continue; // avoid leading zero
            result.add(p[0] + sub + p[1]);
        }
    }
    return result;
}

