    for (int i = 0; i < n; i++) {
        result.add(curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

