    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        addInLexOrder(i, n, result);
    }
    return result;
}

private static void addInLexOrder(int current, int n, List<Integer> list) {
    if (current > n) {
        return;
    }
    list.add(current);
    long base = (long) current * 10;
    if (base > n) {
        return;
    }
    for (int digit = 0; digit < 10; digit++) {
        int next = (int) (base + digit);
        if (next > n) {
            break;
        }
        addInLexOrder(next, n, list);
    }
}

