}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            // Append reversed current word and the space
            result.append(word.reverse());
            word.setLength(0); // reset word builder
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word if any
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < s.length()) {
        // Preserve whitespace characters as they are
        if (Character.isWhitespace(s.charAt(i))) {
            result.append(s.charAt(i));
            i++;
        } else {
            // Identify the start and end of a word
            int start = i;
            while (i < s.length() && !Character.isWhitespace(s.charAt(i))) {
                i++;
            }
            // Append the word in reverse order
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        if (Character.isWhitespace(s.charAt(i))) {
            result.append(s.charAt(i));
            i++;
        } else {
            int start = i;
            while (i < n && !Character.isWhitespace(s.charAt(i))) {
                i++;
            }
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    if (s.length() == 0) {
        return "";
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        if (s.charAt(i) == ' ') {
            // Preserve space
            result.append(' ');
            i++;
            continue;
        }
        // Find the end of the word
        int j = i;
        while (j < n && s.charAt(j) != ' ') {
            j++;
        }
        // Append the word in reverse order
        for (int k = j - 1; k >= i; k--) {
            result.append(s.charAt(k));
        }
        i = j;
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            result.append(c);
            word.setLength(0);
        } else {
            word.append(c);
        }
    }

    // Append the last word after the loop
    result.append(word.reverse());
    return result.toString();
}
